-- Passage rg5-theme-summary-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('dc2beff6-6ff1-5e1c-98e3-22c9ed438ee1', 'rg5-theme-summary-p01', (select id from public.skills where slug = 'read-g5-theme-summary'), null,
        '3-5', $q$Measure Twelve$q$, $q$Amara had two weeks to learn her piece for the spring piano recital. Most of the song was easy. Her fingers knew the first page by heart after only three days.

Measure twelve was different. It had a fast run of notes that climbed up the keys and tumbled back down. Every time Amara reached it, her fingers tangled together like shoelaces. She would bang the keys and start the whole song over from the beginning.

"Why do you keep starting over?" asked her little brother, Kofi, from the couch.

"Because I keep messing up," Amara said.

"But you only mess up one part," Kofi said. "Why not just play that part?"

Amara frowned. Then she tried it. She played measure twelve very slowly, one note at a time. She played it ten times in a row. The next day she played it a little faster. By the end of the week, her fingers moved through the run as smoothly as water.

On the night of the recital, Amara's hands shook as she sat down at the shiny black piano. When she reached measure twelve, she took a breath. Her fingers climbed and tumbled exactly the way she had practiced.

Afterward, Kofi ran up to her. "You didn't start over!" he said.

Amara laughed. "That's because I finally stopped running away from the hard part."$q$, 'draft')
