-- Passage rg5-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('10129b83-73e0-5e8b-80f8-384b42794b81', 'rg5-theme-summary-p02', (select id from public.skills where slug = 'read-g5-theme-summary'), null,
        '3-5', $q$The Spider and the Wind$q$, $q$High on the branch of an apple tree, a spider spent all night weaving a wide, silver web. By morning it sparkled with dew. A grasshopper hopping below stopped to admire it.

"That is the finest web in the whole orchard," the grasshopper said.

That afternoon, a strong wind swept across the hill. It shook the branches and ripped the web into loose threads. The spider clung to a leaf until the wind passed.

The next night, the spider wove the web again in the very same spot. The next afternoon, the wind tore it apart again.

"You are wasting your time," said the grasshopper. "Why not give up and live on the ground like me?"

The spider did not answer. Instead, she climbed down and looked around carefully. She noticed that the wind always came from the west. She also noticed a low branch on the east side of the tree, where the thick trunk blocked the wind.

That night, she wove a smaller web on the low branch. When the wind blew the next afternoon, the web trembled but held. Soon it was full of flies.

The grasshopper looked up in surprise. "So you did not give up after all."

"No," said the spider. "But I did stop doing the same thing and hoping for a different result."$q$, 'draft')
