-- Passage rg5-theme-summary-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('6a521d7e-9df3-5750-a987-bfda36368894', 'rg5-theme-summary-p03', (select id from public.skills where slug = 'read-g5-theme-summary'), null,
        '3-5', $q$Saturday Kite$q$, $q$I ran across the windy field
with string wrapped tight around my fist.
My kite kept diving to the grass.
It spun and crashed and twirled and missed.

I held the string so very close.
I would not let one inch go free.
I was afraid that if I did,
the kite would fly away from me.

My neighbor, Mr. Castillo, laughed
and said, "Just give the string some room."
I let it out a little bit.
The kite climbed up like something bloomed.

It rose above the maple trees.
It rose above the water tower.
The more I trusted it to go,
the more it danced with steady power.

Now when I want to hold on tight
to things I care about the most,
I think about that Saturday
and loosen up my fist, not close.$q$, 'draft')
