  ('30d4a1f9-0f31-5381-906b-4144060afa53', null, (select id from public.skills where slug = 'read-g5-theme-summary'), null, 'medium',
   $q$Which lines best show the change in the speaker's thinking?$q$, $q$[{"text":"\"My kite kept diving to the grass. / It spun and crashed and twirled and missed.\"","is_correct":false,"misconception_token":"wrong-evidence"},{"text":"\"It rose above the maple trees. / It rose above the water tower.\"","is_correct":false,"misconception_token":"too-narrow"},{"text":"\"The more I trusted it to go, / the more it danced with steady power.\"","is_correct":true},{"text":"\"I ran across the windy field / with string wrapped tight around my fist.\"","is_correct":false,"misconception_token":"wrong-evidence"}]$q$::jsonb, $q$"The more I trusted it to go, / the more it danced with steady power."$q$, $q$These lines name the new idea the speaker has learned: trust leads to steady flight. The lines about the maple trees describe how high the kite went, not what the speaker realized.$q$, 'draft', '6a521d7e-9df3-5750-a987-bfda36368894')
