-- Passage rg5-theme-summary-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('258f9122-b6b9-50eb-a014-594b0ffde069', 'rg5-theme-summary-p04', (select id from public.skills where slug = 'read-g5-theme-summary'), null,
        '3-5', $q$The Anchor Leg$q$, $q$Kenji was the slowest swimmer on the Riverside Otters relay team. Everyone knew it, especially Kenji.

The day before the big meet, Coach Adeyemi read the order for the relay. "Kenji, you will swim last," she said. "You are our anchor."

Kenji's stomach dropped. The anchor swimmer finished the race. If he was slow, everyone would see.

That night he told his sister Mei, "I'm going to lose it for the whole team."

Mei shrugged. "Maybe. Or maybe you'll swim your best race. You can't control the other teams. You can only control your own lane."

At the meet, Kenji's teammates swam hard. When the third swimmer touched the wall, the Otters were in fourth place out of six. Kenji dove in.

He did not look at the other lanes. He thought only about his arms, his kicks and his breathing. When he touched the wall, he looked up at the scoreboard. The Otters had finished third.

Kenji had not won the race, but his time was two seconds faster than he had ever swum. His teammates crowded around him, cheering.

"You moved us up a place," said his teammate Rosa.

Kenji grinned, still out of breath. For the first time, he did not feel like the slowest swimmer. He felt like part of the team.$q$, 'draft')
