-- Passage rg5-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f1c42eed-21e9-5053-b322-956d92a86509', 'rg5-theme-summary-p06', (select id from public.skills where slug = 'read-g5-theme-summary'), null,
        '3-5', $q$A Day at Hollow Creek Farm$q$, $q$When Tomas heard that his class was visiting a living history farm, he groaned. "A whole day without screens?" he said.

Hollow Creek Farm looked the way farms did two hundred years ago. A worker named Mrs. Lindqvist wore a long dress and a bonnet. She handed Tomas a heavy wooden bucket.

"Our first job is fetching water from the well," she said. "There are no faucets here."

Tomas carried the bucket across the yard three times. His arms ached. Next, the class took turns churning cream into butter. Tomas pushed the wooden handle up and down for twenty minutes before the cream turned thick and yellow.

At lunch, Mrs. Lindqvist served bread with the butter they had made. Tomas took a bite. It was the best bread he had ever tasted.

"Children back then did these chores every single day," Mrs. Lindqvist said. "Before school, and after."

On the bus ride home, Tomas looked out the window at the houses rolling by. He thought about the kitchens inside them, with faucets and refrigerators.

That evening, his mother asked him to set the table. Usually he complained. This time, he did it without a word. Then he filled everyone's glass with water straight from the faucet and smiled.$q$, 'draft')
