insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('5a896f5c-4474-5deb-981a-f9e2e84c2a08', 'rg5-theme-summary-p07', (select id from public.skills where slug = 'read-g5-theme-summary'), null,
        '3-5', $q$The Maple by the Fence$q$, $q$My grandfather planted it
the year my mother turned nine,
a stick no taller than his knee
beside the wooden fence line.

For years it hardly seemed to grow.
The neighbors said, "Why even try?"
But Grandpa watered it each week
and trusted it would reach the sky.

Now I can climb its lowest limb.
Its shade spreads wide across the lawn.
In fall it drops a rain of gold.
In spring its tiny buds come on.

I used to want things right away:
a skill, a friend, a taller me.
But now I sit beneath its leaves
and think about that patient tree.

The best things do not rush to grow.
They stretch a little every year.
My grandpa knew it when he dug,
and I am learning it this year.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
