  ('5c3856eb-f9de-5d81-93bf-02ecd13677f5', null, (select id from public.skills where slug = 'read-g5-theme-summary'), null, 'hard',
   $q$Why does the author end the story with Mr. Okafor giving Nadia her own clipboard?$q$, $q$[{"text":"To show that Nadia's honesty earned her trust and a bigger role.","is_correct":true},{"text":"To show that Nadia's counting of the sparrows was too slow.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To suggest that Nadia should look harder for owls next year.","is_correct":false,"misconception_token":"misreads-ending"},{"text":"To explain that the nature center ran out of extra clipboards.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$To show that Nadia's honesty earned her trust and a bigger role.$q$, $q$Getting her own clipboard after speaking up shows that Nadia is now trusted as a real volunteer. Nothing suggests the gift is a hint to find owls, since the point was reporting truthfully.$q$, 'draft', '33545167-b92b-5b90-9991-d84dc4cb5d6f')
